"use client"

import * as React from "react"

import { createViewerResource } from "@/lib/viewer-resource"
import { FileThumbnail } from "@/components/ui/file-thumbnail"
import { resolveThumbnailDescriptor } from "@/components/document-thumbnail/descriptor"
import {
  getThumbnailKey,
  getThumbnailRenderKey,
} from "@/components/document-thumbnail/keys"
import { ThumbnailClientPreview } from "@/components/document-thumbnail/thumbnail-client-preview"
import {
  DirectImageThumbnail,
  isDirectImageThumbnail,
} from "@/components/document-thumbnail/thumbnail-direct-image"
import {
  createThumbnailErrorState,
  type ThumbnailErrorState,
} from "@/components/document-thumbnail/thumbnail-error-state"
import { getThumbnailOptions } from "@/components/document-thumbnail/thumbnail-options"
import {
  type DocumentThumbnailProps,
  type ThumbnailAnchor,
} from "@/components/document-thumbnail/types"

export type { DocumentThumbnailProps, ThumbnailAnchor }

/**
 * Generates a first-unit thumbnail for a document — page 1, first sheet, or
 * first slide — then drops it into the dependency-free `FileThumbnail` shell.
 */
export function DocumentThumbnail({
  source,
  as,
  className,
  previewAspectRatio = 3 / 4,
  anchor = "top-left",
  retryKey,
  onError,
}: DocumentThumbnailProps) {
  const descriptor = resolveThumbnailDescriptor({ source, as })
  const resource = React.useMemo(() => createViewerResource(source), [source])
  const thumbnailKey = getThumbnailKey({
    resource,
    descriptor,
    options: getThumbnailOptions(descriptor),
  })
  const renderKey = getThumbnailRenderKey({
    thumbnailKey,
    anchor,
    retryKey: retryKey ?? null,
  })
  const [errorState, setErrorState] =
    React.useState<ThumbnailErrorState | null>(null)
  const currentErrorState =
    errorState?.renderKey === renderKey ? errorState : null
  const directUrl = resource.content.directUrl

  if (descriptor.category === "unsupported") {
    return (
      <FileThumbnail
        file={{ name: descriptor.displayName, type: descriptor.mimeType ?? "" }}
        previewAspectRatio={previewAspectRatio}
        className={className}
      />
    )
  }

  if (isDirectImageThumbnail({ descriptor, directUrl })) {
    return (
      <DirectImageThumbnail
        descriptor={descriptor}
        resource={resource}
        directUrl={directUrl!}
        previewAspectRatio={previewAspectRatio}
        className={className}
        anchor={anchor}
        renderKey={renderKey}
        errorState={currentErrorState}
        onError={(error, nextErrorState) => {
          setErrorState(nextErrorState)
          onError?.(error, nextErrorState.info)
        }}
      />
    )
  }

  return (
    <FileThumbnail
      file={{ name: descriptor.displayName, type: descriptor.mimeType ?? "" }}
      previewAspectRatio={previewAspectRatio}
      className={className}
      state={currentErrorState ? "error" : "loaded"}
      aria-label={currentErrorState?.info.userMessage}
      title={currentErrorState?.info.userMessage}
      data-error-domain={currentErrorState?.info.domain}
      data-error-format={currentErrorState?.info.format}
      data-error-kind={currentErrorState?.info.kind}
      data-error-message={currentErrorState?.info.message}
      previewContent={
        <ThumbnailClientPreview
          key={renderKey}
          resource={resource}
          descriptor={descriptor}
          thumbnailKey={thumbnailKey}
          anchor={anchor}
          onError={(error) => {
            const nextErrorState = createThumbnailErrorState({
              renderKey,
              error,
              resource,
              descriptor,
            })
            setErrorState(nextErrorState)
            onError?.(error, nextErrorState.info)
          }}
        />
      }
    />
  )
}

import {
  extensionOf,
  resolveViewerDescriptor,
  type FileCategory,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export function resolveThumbnailDescriptor({
  source,
  as,
}: {
  source: ViewerSource
  as?: FileCategory
}): ViewerDescriptor {
  return resolveViewerDescriptor({ source, category: as })
}

export function isTiffDescriptor(descriptor: ViewerDescriptor): boolean {
  const mime = descriptor.mimeType?.toLowerCase().split(";")[0].trim()
  if (mime === "image/tiff" || mime === "image/tif") return true
  const extension = extensionOf(descriptor.displayName)
  return extension === "tif" || extension === "tiff"
}

"use client"

import * as React from "react"

// A failed parse updates the outer FileThumbnail state so it degrades to the
// shared fallback surface instead of an empty preview layer.
export class ThumbnailErrorBoundary extends React.Component<
  {
    children: React.ReactNode
    fallback: React.ReactNode
    onError: (error: unknown) => void
  },
  { failed: boolean }
> {
  constructor(props: {
    children: React.ReactNode
    fallback: React.ReactNode
    onError: (error: unknown) => void
  }) {
    super(props)
    this.state = { failed: false }
  }

  static getDerivedStateFromError() {
    return { failed: true }
  }

  componentDidCatch(error: unknown) {
    this.props.onError(error)
  }

  render() {
    if (this.state.failed) return this.props.fallback
    return this.props.children
  }
}

import type * as React from "react"

import type { ViewerResource } from "@/lib/viewer-resource"
import type { ViewerDescriptor } from "@/lib/viewer-source"

import type { ThumbnailAnchor } from "./types"

export interface ThumbnailKeyInput {
  resource: ViewerResource
  descriptor: ViewerDescriptor
  unit?: string
  options?: readonly ThumbnailOption[]
}

export interface ThumbnailRenderKeyInput {
  thumbnailKey: string
  anchor: ThumbnailAnchor
  retryKey: React.Key | null
}

export function getThumbnailKey({
  resource,
  descriptor,
  unit = "first",
  options = [],
}: ThumbnailKeyInput): string {
  return [
    encodePart(`resource:${resource.keys.load}`),
    encodePart(`category:${descriptor.category}`),
    encodePart(`unit:${unit}`),
    ...options.map((option) => encodePart(`option:${option}`)),
  ].join("")
}

export type ThumbnailOption = string & {
  readonly __thumbnailOption: unique symbol
}

export function thumbnailOption(
  name: string,
  value: string | number
): ThumbnailOption {
  return `${name}:${String(value)}` as ThumbnailOption
}

export function getThumbnailRenderKey({
  thumbnailKey,
  anchor,
  retryKey,
}: ThumbnailRenderKeyInput): string {
  return [
    encodePart(`thumbnail:${thumbnailKey}`),
    encodePart(`anchor:${anchor}`),
    encodeRetryKey(retryKey),
  ].join("")
}

function encodePart(value: string): string {
  return `${value.length}:${value}`
}

function encodeRetryKey(retryKey: React.Key | null): string {
  if (retryKey === null) return encodePart("retry:null:")
  return encodePart(`retry:${typeof retryKey}:${String(retryKey)}`)
}

"use client"

import * as React from "react"

import type { ViewerResource } from "@/lib/viewer-resource"
import type { FileCategory, ViewerDescriptor } from "@/lib/viewer-source"

import { isTiffDescriptor } from "./descriptor"
import { CodeThumbnail } from "./renderers/code-thumbnail"
import { CsvFirstRows } from "./renderers/csv-thumbnail"
import { DocxFirstPage } from "./renderers/docx-thumbnail"
import { HtmlFirstPage } from "./renderers/html-thumbnail"
import { ImageFirstFrame } from "./renderers/image-thumbnail"
import { MarkdownFirstPage } from "./renderers/markdown-thumbnail"
import { PdfFirstPage } from "./renderers/pdf-thumbnail"
import { PptxFirstSlide } from "./renderers/pptx-thumbnail"
import { TextThumbnail } from "./renderers/text-thumbnail"
import { TiffFirstPage } from "./renderers/tiff-thumbnail"
import { XlsxFirstSheet } from "./renderers/xlsx-thumbnail"
import { isCodeThumbnailDescriptor } from "./thumbnail-code"
import type { ThumbnailAnchor } from "./types"

type DocumentRenderer = (props: {
  resource: ViewerResource
  descriptor: ViewerDescriptor
  thumbnailKey: string
  anchor: ThumbnailAnchor
  onError: (error: unknown) => void
}) => React.ReactNode

const DOCUMENT_RENDERERS: Record<
  Exclude<FileCategory, "unsupported">,
  DocumentRenderer
> = {
  pdf: ({ resource, anchor }) => (
    <PdfFirstPage resource={resource} anchor={anchor} />
  ),
  xlsx: ({ resource, thumbnailKey }) => (
    <XlsxFirstSheet resource={resource} thumbnailKey={thumbnailKey} />
  ),
  pptx: ({ resource, thumbnailKey, anchor }) => (
    <PptxFirstSlide
      resource={resource}
      thumbnailKey={thumbnailKey}
      anchor={anchor}
    />
  ),
  docx: ({ resource }) => <DocxFirstPage resource={resource} />,
  image: ({ resource, descriptor, thumbnailKey, anchor, onError }) =>
    isTiffDescriptor(descriptor) ? (
      <TiffFirstPage
        resource={resource}
        thumbnailKey={thumbnailKey}
        anchor={anchor}
        onError={onError}
      />
    ) : (
      <ImageFirstFrame resource={resource} anchor={anchor} onError={onError} />
    ),
  csv: ({ resource, thumbnailKey }) => (
    <CsvFirstRows resource={resource} thumbnailKey={thumbnailKey} />
  ),
  markdown: ({ resource, thumbnailKey }) => (
    <MarkdownFirstPage resource={resource} thumbnailKey={thumbnailKey} />
  ),
  html: ({ resource, thumbnailKey }) => (
    <HtmlFirstPage resource={resource} thumbnailKey={thumbnailKey} />
  ),
  text: ({ resource, descriptor, thumbnailKey }) =>
    isCodeThumbnailDescriptor(descriptor) ? (
      <CodeThumbnail resource={resource} thumbnailKey={thumbnailKey} />
    ) : (
      <TextThumbnail resource={resource} thumbnailKey={thumbnailKey} />
    ),
}

export function FirstThumbnailUnit({
  resource,
  descriptor,
  thumbnailKey,
  anchor,
  onError,
}: {
  resource: ViewerResource
  descriptor: ViewerDescriptor
  thumbnailKey: string
  anchor: ThumbnailAnchor
  onError: (error: unknown) => void
}) {
  if (descriptor.category === "unsupported") return null
  const render = DOCUMENT_RENDERERS[descriptor.category]
  return render({ resource, descriptor, thumbnailKey, anchor, onError })
}

import { registerThumbnailTestReset } from "./thumbnail-test-reset"

export interface ThumbnailCacheEntry<T> {
  promise: Promise<T>
  status: "pending" | "resolved" | "rejected"
  value?: T
  onResolve?: (value: T) => void
}

export interface ThumbnailCacheStore<T> {
  get(key: string): ThumbnailCacheEntry<T> | undefined
  set(key: string, entry: ThumbnailCacheEntry<T>): void
  delete(key: string): boolean
  clear?(): void
  prune?(): void
}

export interface ThumbnailArtifactCacheOptions<T> {
  maxEntries: number
  dispose?: (value: T) => void
}

export interface ThumbnailArtifactCache<T> extends ThumbnailCacheStore<T> {
  readonly size: number
  clear(): void
  prune(): void
}

export function cachedThumbnailResource<T>(
  cache: ThumbnailCacheStore<T>,
  key: string,
  load: () => Promise<T>
): Promise<T> {
  const cached = cache.get(key)
  if (cached) {
    if (cached.status === "rejected") {
      cache.delete(key)
    }
    return cached.promise
  }

  const entry: ThumbnailCacheEntry<T> = {
    status: "pending",
    promise: load().then(
      (value) => {
        entry.status = "resolved"
        entry.value = value
        entry.onResolve?.(value)
        cache.prune?.()
        return value
      },
      (error) => {
        entry.status = "rejected"
        throw error
      }
    ),
  }
  cache.set(key, entry)
  return entry.promise
}

export function createThumbnailArtifactCache<T>({
  maxEntries,
  dispose,
}: ThumbnailArtifactCacheOptions<T>): ThumbnailArtifactCache<T> {
  const entries = new Map<string, ThumbnailCacheEntry<T>>()

  const cache: ThumbnailArtifactCache<T> = {
    get size() {
      return entries.size
    },
    get(key) {
      const entry = entries.get(key)
      if (!entry) return undefined
      entries.delete(key)
      entries.set(key, entry)
      return entry
    },
    set(key, entry) {
      entries.set(key, entry)
      entry.onResolve = (value) => {
        if (entries.get(key) !== entry) dispose?.(value)
      }
      cache.prune?.()
    },
    delete(key) {
      const entry = entries.get(key)
      if (!entry) return false
      entries.delete(key)
      disposeCacheEntry(entry, dispose)
      return true
    },
    clear() {
      for (const entry of entries.values()) {
        disposeCacheEntry(entry, dispose)
      }
      entries.clear()
    },
    prune() {
      while (entries.size > maxEntries) {
        const evicted = evictOldestResolvedEntry(entries, dispose)
        if (!evicted) return
      }
    },
  }

  registerThumbnailTestReset(() => cache.clear?.())

  return cache
}

function evictOldestResolvedEntry<T>(
  entries: Map<string, ThumbnailCacheEntry<T>>,
  dispose?: (value: T) => void
): boolean {
  for (const [key, entry] of entries) {
    if (entry.status !== "pending") {
      entries.delete(key)
      disposeCacheEntry(entry, dispose)
      return true
    }
  }
  return false
}

function disposeCacheEntry<T>(
  entry: ThumbnailCacheEntry<T>,
  dispose?: (value: T) => void
) {
  if (entry.status === "resolved" && entry.value !== undefined) {
    dispose?.(entry.value)
  }
}

"use client"

import * as React from "react"

import type { ViewerResource } from "@/lib/viewer-resource"
import type { ViewerDescriptor } from "@/lib/viewer-source"
import { FileThumbnailShimmer } from "@/components/ui/file-thumbnail"
import { useIsClient } from "@/components/ui/use-is-client"

import { ThumbnailErrorBoundary } from "./errors"
import { FirstThumbnailUnit } from "./renderer-registry"
import { useThumbnailInView } from "./thumbnail-in-view"
import type { ThumbnailAnchor } from "./types"

export function ThumbnailClientPreview({
  resource,
  descriptor,
  thumbnailKey,
  anchor,
  onError,
}: {
  resource: ViewerResource
  descriptor: ViewerDescriptor
  thumbnailKey: string
  anchor: ThumbnailAnchor
  onError: (error: unknown) => void
}) {
  const isClient = useIsClient()
  const { ref: inViewRef, seen: isSeen } = useThumbnailInView()

  return (
    <div ref={inViewRef} className="absolute inset-0">
      {isClient && isSeen ? (
        <ThumbnailErrorBoundary fallback={null} onError={onError}>
          <React.Suspense fallback={<FileThumbnailShimmer />}>
            <FirstThumbnailUnit
              resource={resource}
              descriptor={descriptor}
              thumbnailKey={thumbnailKey}
              anchor={anchor}
              onError={onError}
            />
          </React.Suspense>
        </ThumbnailErrorBoundary>
      ) : (
        <FileThumbnailShimmer />
      )}
    </div>
  )
}

import { registerThumbnailTestReset } from "./thumbnail-test-reset"

const MAX_CONCURRENT_DECODES = 3
let activeDecodes = 0
let decodeGeneration = 0
const decodeQueue: Array<() => void> = []

function acquireThumbnailDecodeSlot(): Promise<() => void> {
  return new Promise((resolve) => {
    const generation = decodeGeneration
    const grant = () => {
      if (generation !== decodeGeneration) return
      activeDecodes++
      let hasReleased = false
      resolve(() => {
        if (hasReleased) return
        hasReleased = true
        if (generation !== decodeGeneration) return
        activeDecodes--
        decodeQueue.shift()?.()
      })
    }
    if (activeDecodes < MAX_CONCURRENT_DECODES) grant()
    else decodeQueue.push(grant)
  })
}

export async function withThumbnailDecodeSlot<T>(
  fn: () => Promise<T>
): Promise<T> {
  const release = await acquireThumbnailDecodeSlot()
  try {
    return await fn()
  } finally {
    release()
  }
}

export function getThumbnailDecodeQueueSnapshot() {
  return {
    activeDecodes,
    queuedDecodes: decodeQueue.length,
    maxConcurrentDecodes: MAX_CONCURRENT_DECODES,
  }
}

function resetThumbnailDecodeQueueForTests() {
  decodeGeneration++
  activeDecodes = 0
  decodeQueue.splice(0)
}

registerThumbnailTestReset(resetThumbnailDecodeQueueForTests)

"use client"

import type { ViewerResource } from "@/lib/viewer-resource"
import type { ViewerDescriptor } from "@/lib/viewer-source"
import { FileThumbnail } from "@/components/ui/file-thumbnail"

import { isTiffDescriptor } from "./descriptor"
import {
  createThumbnailErrorState,
  type ThumbnailErrorState,
} from "./thumbnail-error-state"
import { createThumbnailImageLoadError } from "./thumbnail-errors"
import { ANCHOR_OBJECT_POSITION, type ThumbnailAnchor } from "./types"

export function isDirectImageThumbnail({
  descriptor,
  directUrl,
}: {
  descriptor: ViewerDescriptor
  directUrl?: string | null
}): boolean {
  return (
    descriptor.category === "image" &&
    !isTiffDescriptor(descriptor) &&
    Boolean(directUrl)
  )
}

export function DirectImageThumbnail({
  descriptor,
  resource,
  directUrl,
  previewAspectRatio,
  className,
  anchor,
  renderKey,
  errorState,
  onError,
}: {
  descriptor: ViewerDescriptor
  resource: ViewerResource
  directUrl: string
  previewAspectRatio: number
  className?: string
  anchor: ThumbnailAnchor
  renderKey: string
  errorState: ThumbnailErrorState | null
  onError?: (error: unknown, errorState: ThumbnailErrorState) => void
}) {
  const failedDirectImage =
    errorState?.info.format === "image" ? errorState : null

  return (
    <FileThumbnail
      file={{ name: descriptor.displayName, type: descriptor.mimeType ?? "" }}
      previewImageUrl={directUrl}
      previewAspectRatio={previewAspectRatio}
      className={className}
      previewClassName={ANCHOR_OBJECT_POSITION[anchor]}
      state={failedDirectImage ? "error" : "loaded"}
      aria-label={failedDirectImage?.info.userMessage}
      title={failedDirectImage?.info.userMessage}
      data-error-domain={failedDirectImage?.info.domain}
      data-error-format={failedDirectImage?.info.format}
      data-error-kind={failedDirectImage?.info.kind}
      data-error-message={failedDirectImage?.info.message}
      onPreviewError={() => {
        const error = createThumbnailImageLoadError()
        const nextErrorState = createThumbnailErrorState({
          renderKey,
          error,
          resource,
          descriptor,
        })
        onError?.(error, nextErrorState)
      }}
    />
  )
}

import { toViewerErrorInfo, type ViewerErrorInfo } from "@/lib/viewer-errors"
import type { ViewerResource } from "@/lib/viewer-resource"
import type { ViewerDescriptor } from "@/lib/viewer-source"

import { thumbnailCategoryFormat } from "./thumbnail-errors"

export interface ThumbnailErrorState {
  renderKey: string
  info: ViewerErrorInfo
}

export function createThumbnailErrorState({
  renderKey,
  error,
  resource,
  descriptor,
}: {
  renderKey: string
  error: unknown
  resource: ViewerResource
  descriptor: ViewerDescriptor
}): ThumbnailErrorState {
  return {
    renderKey,
    info: toViewerErrorInfo(error, {
      format: thumbnailCategoryFormat(descriptor.category),
      sourceKind: resource.sourceKind,
      canDownload: !resource.originalDownload.isDisabled,
    }),
  }
}

import {
  isResourceError,
  ViewerFormatError,
  type ViewerFormat,
} from "@/lib/viewer-errors"
import type { FileCategory } from "@/lib/viewer-source"

export async function withThumbnailFormatError<T>(
  category: FileCategory,
  kind:
    | "decode_failed"
    | "load_failed"
    | "parse_failed"
    | "render_failed"
    | "unknown",
  fileName: string,
  message: string,
  load: () => Promise<T>
): Promise<T> {
  try {
    return await load()
  } catch (error) {
    if (isResourceError(error)) throw error
    throw new ViewerFormatError({
      format: thumbnailCategoryFormat(category),
      kind,
      message: `${message}: ${fileName}`,
      cause: error,
    })
  }
}

export function createThumbnailImageLoadError(): ViewerFormatError {
  return new ViewerFormatError({
    format: "image",
    kind: "load_failed",
    message: "Could not load image preview.",
  })
}

export function thumbnailCategoryFormat(category: FileCategory): ViewerFormat {
  if (category === "markdown" || category === "html") return "text"
  if (category === "unsupported") return "file"
  return category
}

"use client"

import * as React from "react"

export function useThumbnailInView() {
  const [seen, setSeen] = React.useState(false)
  const [node, setNode] = React.useState<HTMLElement | null>(null)
  const seenRef = React.useRef(false)
  const ref = React.useCallback((el: HTMLElement | null) => setNode(el), [])

  React.useEffect(() => {
    if (!node || seenRef.current) return
    if (typeof IntersectionObserver === "undefined") {
      seenRef.current = true
      setSeen(true)
      return
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          seenRef.current = true
          setSeen(true)
          observer.disconnect()
        }
      },
      { rootMargin: "300px" }
    )
    observer.observe(node)
    return () => observer.disconnect()
  }, [node])

  return { ref, seen }
}

import type { ThumbnailFileMeta } from "./thumbnail-text"

/**
 * Profiling helper: logs `[thumb] <label> <ms>` when enabled. Gated on a global
 * so it costs nothing in normal use; the profiler sets it before navigation.
 */
export async function timedThumbnail<T>(
  label: string,
  fn: () => Promise<T>
): Promise<T> {
  const on =
    typeof globalThis !== "undefined" &&
    (globalThis as { __THUMB_PROFILE__?: boolean }).__THUMB_PROFILE__
  if (!on) return fn()
  const t0 = performance.now()
  try {
    return await fn()
  } finally {
    console.log(`[thumb] ${label} ${(performance.now() - t0).toFixed(1)}ms`)
  }
}

export function shortName(meta: ThumbnailFileMeta): string {
  return meta.fileName
}

import { registerThumbnailTestReset } from "./thumbnail-test-reset"

export function useThumbnailResource<T>(promise: Promise<T>): T {
  const record = getThumbnailResourceRecord(promise)
  if (record.status === "pending") throw record.promise
  if (record.status === "rejected") throw record.error
  return record.value as T
}

let thumbnailResourceRecords = new WeakMap<
  Promise<unknown>,
  ThumbnailResourceRecord<unknown>
>()

function getThumbnailResourceRecord<T>(
  promise: Promise<T>
): ThumbnailResourceRecord<T> {
  const cached = thumbnailResourceRecords.get(promise) as
    | ThumbnailResourceRecord<T>
    | undefined
  if (cached) return cached

  const record: ThumbnailResourceRecord<T> = {
    promise,
    status: "pending",
  }
  promise.then(
    (value) => {
      record.status = "resolved"
      record.value = value
    },
    (error) => {
      record.status = "rejected"
      record.error = error
    }
  )
  thumbnailResourceRecords.set(promise, record)
  return record
}

interface ThumbnailResourceRecord<T> {
  promise: Promise<T>
  status: "pending" | "resolved" | "rejected"
  value?: T
  error?: unknown
}

function resetThumbnailResourceRecordsForTests() {
  thumbnailResourceRecords = new WeakMap()
}

registerThumbnailTestReset(resetThumbnailResourceRecordsForTests)

const resetHandlers = new Set<() => void>()

export function registerThumbnailTestReset(handler: () => void): () => void {
  resetHandlers.add(handler)
  return () => {
    resetHandlers.delete(handler)
  }
}

export function clearThumbnailCachesForTests() {
  for (const reset of [...resetHandlers]) reset()
}

import {
  isAbortError,
  isResourceError,
  ResourceError,
} from "@/lib/viewer-errors"
import type {
  ViewerContentBytes,
  ViewerContentIdentity,
  ViewerContentRange,
  ViewerContentStream,
} from "@/lib/viewer-resource"
import type { ViewerSource } from "@/lib/viewer-source"

import {
  cachedThumbnailResource,
  createThumbnailArtifactCache,
} from "./thumbnail-cache"
import {
  TEXT_THUMBNAIL_CACHE_MAX_ENTRIES,
  TEXT_THUMBNAIL_MAX_BYTES,
} from "./thumbnail-limits"
import { shortName, timedThumbnail } from "./thumbnail-profile"

export interface ThumbnailFileMeta {
  fileName: string
  mimeType?: string
  sourceKind: ViewerSource["kind"]
}

export type ThumbnailTextContent = ViewerContentIdentity &
  ViewerContentRange &
  ViewerContentStream

export type ThumbnailBytesContent = ViewerContentIdentity & ViewerContentBytes

const textCache = createThumbnailArtifactCache<string>({
  maxEntries: TEXT_THUMBNAIL_CACHE_MAX_ENTRIES,
})

export function getThumbnailText(
  meta: ThumbnailFileMeta,
  content: ThumbnailTextContent,
  thumbnailKey: string
): Promise<string> {
  return cachedThumbnailResource(textCache, thumbnailKey, () =>
    timedThumbnail(`text:fetch ${shortName(meta)}`, async () => {
      if (meta.sourceKind === "url" || content.sourceKind === "url") {
        try {
          return await readThumbnailTextRange(content)
        } catch (error) {
          if (shouldReadTextStreamPrefix(error)) {
            return readThumbnailTextStreamPrefix(content)
          }
          throw error
        }
      }
      return readThumbnailTextRange(content)
    })
  )
}

export function thumbnailFileMeta({
  fileName,
  mimeType,
  sourceKind,
}: ThumbnailFileMeta): ThumbnailFileMeta {
  return { fileName, mimeType, sourceKind }
}

function shouldReadTextStreamPrefix(error: unknown): boolean {
  const candidate = resourceErrorCandidate(error)
  return Boolean(
    candidate &&
    (candidate.kind === "invalid_range" ||
      (candidate.kind === "http_error" && candidate.status === 416))
  )
}

function resourceErrorCandidate(error: unknown):
  | {
      kind?: unknown
      status?: unknown
    }
  | undefined {
  if (!error || typeof error !== "object") return undefined
  return error as { kind?: unknown; status?: unknown }
}

async function readThumbnailTextRange(content: ThumbnailTextContent) {
  const range = await content.readRange({
    start: 0,
    end: TEXT_THUMBNAIL_MAX_BYTES - 1,
  })
  return new TextDecoder().decode(range.buffer)
}

async function readThumbnailTextStreamPrefix(content: ThumbnailTextContent) {
  const stream = await content.readStream()
  const reader = stream.getReader()
  const decoder = new TextDecoder()
  let remainingBytes = TEXT_THUMBNAIL_MAX_BYTES
  let text = ""

  try {
    while (remainingBytes > 0) {
      const { done, value } = await reader.read()
      if (done) return text + decoder.decode()

      const chunk =
        value.byteLength > remainingBytes
          ? value.slice(0, remainingBytes)
          : value
      text += decoder.decode(chunk, { stream: true })
      remainingBytes -= chunk.byteLength

      if (chunk.byteLength < value.byteLength || remainingBytes === 0) {
        cancelThumbnailTextReader(reader)
        return text + decoder.decode()
      }
    }

    cancelThumbnailTextReader(reader)
    return text + decoder.decode()
  } catch (error) {
    throw createThumbnailTextReadError(error)
  }
}

function createThumbnailTextReadError(error: unknown): ResourceError {
  if (isResourceError(error)) return error
  if (isAbortError(error)) {
    return new ResourceError({
      kind: "aborted",
      message: "Resource load was aborted.",
      cause: error,
    })
  }
  return new ResourceError({
    kind: "fetch_failed",
    message: "Could not read this resource.",
    cause: error,
  })
}

function cancelThumbnailTextReader(
  reader: ReadableStreamDefaultReader<Uint8Array>
) {
  try {
    void reader.cancel().catch(() => {})
  } catch {
    /* The preview prefix is already available; cancellation is best-effort. */
  }
}

import { registerThumbnailTestReset } from "./thumbnail-test-reset"

export interface ThumbnailWorkerMessage {
  id: number
}

export interface ThumbnailWorkerClientOptions<Request, Response> {
  createWorker: () => Worker
  resolve: (response: Response) => unknown
  reject: (response: Response) => string | Error
}

export interface ThumbnailWorkerRequest<Request> {
  request: Request
  transfer?: Transferable[]
}

export interface ThumbnailWorkerClient<Request, Response> {
  request<T = unknown>(input: ThumbnailWorkerRequest<Request>): Promise<T>
  reset(): void
  pendingCount(): number
}

export function createThumbnailWorkerClient<
  Request extends ThumbnailWorkerMessage,
  Response extends ThumbnailWorkerMessage,
>({
  createWorker,
  resolve,
  reject,
}: ThumbnailWorkerClientOptions<Request, Response>): ThumbnailWorkerClient<
  Omit<Request, "id">,
  Response
> {
  let worker: Worker | null = null
  let requestId = 0
  const pending = new Map<
    number,
    { resolve: (value: unknown) => void; reject: (error: Error) => void }
  >()

  const getWorker = () => {
    if (!worker) {
      const nextWorker = createWorker()
      worker = nextWorker
      nextWorker.onmessage = (event: MessageEvent<Response>) => {
        if (worker !== nextWorker) return
        const response = event.data
        const entry = pending.get(response.id)
        if (!entry) return
        pending.delete(response.id)
        try {
          const value = resolve(response)
          if (value !== undefined) entry.resolve(value)
          else entry.reject(toWorkerError(reject(response)))
        } catch (error) {
          entry.reject(toWorkerError(error))
        }
      }
      nextWorker.onerror = (event) => {
        if (worker !== nextWorker) return
        nextWorker.terminate()
        worker = null
        requestId = 0
        rejectPendingRequests(
          event.error instanceof Error
            ? event.error
            : new Error(event.message || "Thumbnail worker failed.")
        )
      }
    }
    return worker
  }

  const rejectPendingRequests = (error: Error) => {
    for (const entry of pending.values()) entry.reject(error)
    pending.clear()
  }

  const reset = () => {
    worker?.terminate()
    worker = null
    requestId = 0
    rejectPendingRequests(new Error("Thumbnail worker reset."))
  }

  const client: ThumbnailWorkerClient<Omit<Request, "id">, Response> = {
    request<T = unknown>(
      input: ThumbnailWorkerRequest<Omit<Request, "id">>
    ): Promise<T> {
      const { request, transfer } = input
      const id = ++requestId
      return new Promise<T>((resolveRequest, rejectRequest) => {
        pending.set(id, {
          resolve: (value) => resolveRequest(value as T),
          reject: rejectRequest,
        })
        try {
          getWorker().postMessage({ id, ...request }, transfer ?? [])
        } catch (error) {
          pending.delete(id)
          rejectRequest(toWorkerError(error))
        }
      })
    },
    reset,
    pendingCount: () => pending.size,
  }

  registerThumbnailTestReset(reset)

  return client
}

function toWorkerError(error: unknown): Error {
  if (error instanceof Error) return error
  return new Error(String(error || "Thumbnail worker failed."))
}

